from .ranges import InvalidRange, bounds


def serve(data, range_header=None):
    """Serve `data` (bytes) for an optional single `bytes=` range header.

    Returns (status, headers, body).  No range returns 200 with the full data;
    one satisfiable range returns 206; an unsatisfiable or invalid range
    returns 416 with an empty body and ``Content-Range: bytes */<length>``.
    """
    length = len(data)

    if range_header is None:
        return 200, {'Content-Length': str(length)}, data

    try:
        start, end = bounds(range_header, length)
    except InvalidRange:
        return (
            416,
            {'Content-Length': '0', 'Content-Range': f'bytes */{length}'},
            b'',
        )

    body = data[start:end + 1]
    return (
        206,
        {
            'Content-Length': str(len(body)),
            'Content-Range': f'bytes {start}-{end}/{length}',
        },
        body,
    )
